tool_input.command:
cd "C:/claudecode/dark raiders" && S="C:/Users/VMOCT2~1/AppData/Local/Temp/claude/C--claudecode-dark-raiders/d3464bd7-c1ab-4c5d-8362-db4589cc478c/scratchpad" && cat > "$S/mk-cw-airlow.ps1" <<'EOF'
# cw-airlow: his order (2026-10-20) "airstrike bar needs to be much lower"
$g=[IO.File]::ReadAllText('C:\claudecode\dark raiders\dark_raiders.html')
function L([string]$rx){ $m=[regex]::Matches($g,$rx); if($m.Count -ne 1){ throw "anchor $rx matched $($m.Count)" }; return $m[0].Value.Replace("`r",'') }
$a1=L "  y=Math\.round\(top-64\*z-g8-bh\);"
$chk=@'
  {v:'VER',what:'cw-airlow, his order (2026-10-20) airstrike bar needs to be much lower: with an empty hand the air-strike plate stands 8px (times the HUD zoom) over the belt top at 1080p and 4k, and with a held item it still clears the held-item panel and the belt',
   run:function(){
     if(!(window.__deploy&&window.__state&&window.__endRaid)||typeof airPlateAt!=='function'||typeof drawHand!=='function') return 'SKIP: no raid or held-item renderer';
     var bad=[], g, p, ow=W, oh=H, hp=hudPlate, hc, oldHand, oldWheel, gear, edges, no=NET.on, sizes=[[1920,1080],[3840,2160]], i, z, bw, bh, y, right, hand, box, empty, g8;
     try{
       __runPrep(); __topClear(); __resetCfg(); __pinDefaults(0); __cleanProfile();
       __deploy({kit:[],safe:null,mapIx:0,seed:4242}); g=__state();
       if(!g||g.over||!g.player) return 'SKIP: no live raid';
       p=g.player; hc=g.hotCells; oldHand=p.hand; oldWheel=g.wheel; gear=HUDBOX.gear; edges=EDGEBOX;
       HUDBOX.gear=null; EDGEBOX={}; g.wheel=null; NET.on=false;
       for(i=0;i<sizes.length;i++){
         W=sizes[i][0]; H=sizes[i][1]; z=Math.max(1,hudRes()); g8=Math.round(8*z);
         y=H-110*z; right=W/2+160*z; bw=LH(200)*z; bh=LH(28)*z;
         g.hotCells=[{x:W/2-200*z,y:y,w:80*z,h:80*z},{x:right-80*z,y:y,w:80*z,h:80*z}];
         p.hand=null; empty=airPlateAt(bw,bh,z);
         if(Math.abs((y-(empty.y+bh))-g8)>1) bad.push(W+': gap over the belt is '+Math.round(y-(empty.y+bh))+', not '+g8);
         if(Math.abs(empty.x+bw-right)>1) bad.push(W+': the plate lost the belt right edge');
         p.hand={k:'bandage',t:0.4,len:1.2}; hand=null;
         hudPlate=function(x,y2,w,h){ if(!hand) hand={x:x,y:y2,w:w,h:h}; return hp.apply(this,arguments); };
         try{ drawHand(); }finally{hudPlate=hp;}
         if(!hand){bad.push(W+': no held-item panel');continue;}
         box=airPlateAt(bw,bh,z);
         if(box.x<hand.x+hand.w&&box.x+bw>hand.x&&box.y<hand.y+hand.h&&box.y+bh>hand.y) bad.push(W+': plate overlaps the held item');
         if(box.y+bh>y) bad.push(W+': plate overlaps the belt');
       }
       return bad.length?bad.join('; '):null;
     }finally{
       hudPlate=hp; W=ow; H=oh; NET.on=no;
       if(g&&p){g.hotCells=hc;p.hand=oldHand;g.wheel=oldWheel;} if(gear!==undefined)HUDBOX.gear=gear; if(edges!==undefined)EDGEBOX=edges;
       try{if(__state()&&!__state().over)__endRaid('abandon');}catch(_e){} __topClear(); __resetCfg(); __cleanProfile();
     }
   }},
'@.Replace("`r",'')
$cm=@'
  // v33.39 (cw-airlow), HIS ORDER (2026-10-20): "airstrike bar needs to be much lower". The 64 px lift is gone: the plate stands 8 px over the belt; the loop below still lifts it clear of the held item and other boxes.
  y=Math.round(top-g8-bh);
'@
$d=[ordered]@{
  title='air strike bar sits just over the belt'
  why='His order (2026-10-20): "airstrike bar needs to be much lower". The plate floated 64 px (times HUD zoom) above the usual gap over the belt. The lift is gone, so it stands 8 px over the belt at the right end; the clearance loop still moves it up only when the held-item panel or another box is in the way.'
  now='The air strike bar sits just over the belt.'
  edits=@( [ordered]@{ anchor=$a1; replacement=$cm.Replace("`r",'').TrimEnd("`n") } )
  check=$chk
}
[IO.File]::WriteAllText('C:\claudecode\dark raiders\tools\handoff\drafts\draft-cw-airlow.json',($d | ConvertTo-Json -Depth 6),(New-Object Text.UTF8Encoding $false))
'written'
EOF
powershell -NoProfile -ExecutionPolicy Bypass -File "$S/mk-cw-airlow.ps1"
